#!/usr/bin/env bash
# Превращает вывод упавшего инструмента в аннотацию GitHub Actions.
#
# Зачем: логи прогона и сводка задания доступны только администратору
# репозитория, а аннотации отдаются публичным API. Без этого причина падения
# видна лишь тому, у кого есть права, — то есть прогон перестаёт быть
# страховочной сеткой для всех остальных.
#
# Использование: .github/annotate.sh <заголовок> <файл с выводом>
set -u

title="$1"
log="$2"

# Аннотация — одна строка: перевод строки кодируется как %0A, а сам знак
# процента должен быть закодирован первым, иначе испортит остальные замены.
message=$(head -c 4000 "$log" | python3 -c '
import sys
text = sys.stdin.read()
for a, b in (("%", "%25"), ("\r", "%0D"), ("\n", "%0A")):
    text = text.replace(a, b)
print(text)
')

echo "::error title=${title}::${message}"
